mapper.select:
SELECT t_maintaining_record.sprinkler_serial, ret_warehouse_date, t_sprinkler.allocate_date, -- 计算日期差（单位：天） DATEDIFF(ret_warehouse_date, t_sprinkler.allocate_date) AS using_days FROM t_maintaining_record LEFT JOIN t_sprinkler ON t_sprinkler.sprinkler_id = t_maintaining_record.sprinkler_id
ret_warehouse_type = "破损仓"
AND DATE_FORMAT(ret_warehouse_date, '%Y-%m-%d') >= #{startDate}
AND DATE_FORMAT(ret_warehouse_date, '%Y-%m-%d') <= #{endDate}
AND t_maintaining_record.sprinkler_serial LIKE '%-%'
AND t_maintaining_record.sprinkler_serial LIKE '66L%'
